fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Get the number of chars in the string
    let len = txt.chars().count();

    if len == 0 {
        return false;
    }

    // We can safely unwrap here since len >= 1
    let mut chars = txt.chars();

    // Get the last character
    let last_char = chars.clone().nth(len - 1).unwrap();

    // Check if last_char is ASCII letter
    let is_ascii_letter = (last_char >= 'a' && last_char <= 'z') || (last_char >= 'A' && last_char <= 'Z');

    if !is_ascii_letter {
        return false;
    }

    if len == 1 {
        return true;
    } else {
        // Get the char before the last one
        let before_last_char = chars.nth(len - 2).unwrap();
        return before_last_char == ' ';
    }
}